"""Original, offline practice: simple classes and virtual TXT/CSV/JSON files.

All files exist only inside MiniPython's memory and cannot affect the host OS.
This is a supported subset of Python, not arbitrary CPython execution.
"""


def item(i, group, name, intro, rules, example, task, starter, solution, tests, hints):
    return dict(id=f'adv{i:02d}', track='advanced',module=group,title=name,
                intro=intro,theory=rules,example=example,task=task,
                starter=starter,solution=solution,cases=tests,hints=hints)


def test(output, *inputs, files=None, expected_files=None):
    value=dict(stdin=list(inputs),stdout=str(output))
    if files is not None: value['files']=files
    if expected_files is not None: value['expected_files']=expected_files
    return value


